 const fractal_module_registration m[]={R(fractal_formula_mandelbrot),R(fractal_formula_julia),R(fractal_numeric_binary64),R(fractal_compute_scalar_v1),R(fractal_compute_conventional),R(fractal_refinement_none),R(fractal_refinement_cdc_unavailable),R(fractal_scheduler_serial),R(fractal_scheduler_serial_v1),R(fractal_scheduler_thread_pool_v1),R(fractal_raster_native),R(fractal_encoder_bmp),R(fractal_memory_system_module),R(fractal_memory_ouro_unavailable_module),R(fractal_telemetry_noop),R(fractal_platform_host),R(fractal_artifact_sink_memory),R(fractal_artifact_sink_host_file),R(fractal_analyzer_passthrough),R(fractal_analyzer_escape_classification_summary),R(fractal_analyzer_iteration_histogram),R(fractal_analyzer_spatial_workload_grid)};
